Here is the commit message:
RDMA/ionic: Fix potential NULL pointer dereference in
 ionic_query_port

The function ionic_query_port() calls ib_device_get_netdev() without
checking the return value which could lead to NULL pointer dereference,
Fix it by checking the return value and return -ENODEV if the 'ndev' is
NULL.

Fixes: 2075bbe8ef03 ("RDMA/ionic: Register device ops for miscellaneous functionality")
Signed-off-by: Kamal Heib <kheib@redhat.com>
Link: https://patch.msgid.link/20260220222125.16973-2-kheib@redhat.com
Signed-off-by: Leon Romanovsky <leon@kernel.org>

Here is the root cause:
The function `ionic_query_port()` calls `ib_device_get_netdev()` which can return NULL (e.g., when no network device is associated with the port), but the return value was not checked before dereferencing `ndev`. This leads to a potential NULL pointer dereference when accessing `ndev` for `netif_running()` and `netif_carrier_ok()`.

Here is the patch:

 static int ionic_query_port(struct ib_device *ibdev, u32 port,
 			    struct ib_port_attr *attr)
 {
 	struct net_device *ndev;

 	if (port != 1)
 		return -EINVAL;

 	ndev = ib_device_get_netdev(ibdev, port);
+	if (!ndev)
+		return -ENODEV;

 	if (netif_running(ndev) && netif_carrier_ok(ndev)) {
 		attr->state = IB_PORT_ACTIVE;
 		attr->phys_state = IB_PORT_PHYS_STATE_LINK_UP;
 	} else if (netif_running(ndev)) {
 		attr->state = IB_PORT_DOWN;
 		attr->phys_state = IB_PORT_PHYS_STATE_POLLING;
 	} else {
 		attr->state = IB_PORT_DOWN;
 		attr->phys_state = IB_PORT_PHYS_STATE_DISABLED;
 	}

 	attr->max_mtu = iboe_get_mtu(ndev->max_mtu);
 	attr->active_mtu = min(attr->max_mtu, iboe_get_mtu(ndev->mtu));
 	attr->gid_tbl_len = IONIC_GID_TBL_LEN;
 	attr->ip_gids = true;
 	attr->port_cap_flags = 0;
 	attr->max_msg_sz = 0x80000000;
 	attr->pkey_tbl_len = IONIC_PKEY_TBL_LEN;
 	attr->max_vl_num = 1;
 	attr->subnet_prefix = 0xfe80000000000000ull;

 	dev_put(ndev);

 	return ib_get_eth_speed(ibdev, port,
 				&attr->active_speed,
 				&attr->active_width);
 }



